const API_BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL;

if (!API_BASE_URL) {
  throw new Error("NEXT_PUBLIC_API_BASE_URL is not defined");
}

async function safeFetch(url: string) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 8000);

  try {
    const res = await fetch(url, {
      cache: "no-store",
      signal: controller.signal,
    });

    if (!res.ok) {
      const text = await res.text();
      throw new Error(text);
    }

    return res.json();
  } finally {
    clearTimeout(timeout);
  }
}

// -----------------------------
// Restaurants
// -----------------------------
export function getRestaurants(params: string = "") {
  return safeFetch(`${API_BASE_URL}/restaurants${params}`);
}

export function getRestaurant(id: string) {
  return safeFetch(`${API_BASE_URL}/restaurants/${id}`);
}

// -----------------------------
// Products / Menu
// -----------------------------
export function getProducts(restaurantId: string) {
  return safeFetch(
    `${API_BASE_URL}/restaurants/${restaurantId}/products`
  );
}
